add_action( 'woocommerce_checkout_update_order_review', 'perfectpixel_tax_exempt_review' );
add_action( 'woocommerce_checkout_process', 'perfectpixel_tax_exempt_process' );

function perfectpixel_tax_exempt_apply( $value ) {
	if ( ! WC()->customer ) {
		return;
	}
	$values = array_filter( array_map( 'trim', explode( ',', strtoupper( '{{tax_exempt_values}}' ) ) ), 'strlen' );
	WC()->customer->set_is_vat_exempt( in_array( strtoupper( trim( (string) $value ) ), $values, true ) );
}

function perfectpixel_tax_exempt_review( $posted ) {
	parse_str( (string) $posted, $data );
	perfectpixel_tax_exempt_apply( $data['{{tax_exempt_field}}'] ?? '' );
}

function perfectpixel_tax_exempt_process() {
	perfectpixel_tax_exempt_apply( isset( $_POST['{{tax_exempt_field}}'] ) ? sanitize_text_field( wp_unslash( $_POST['{{tax_exempt_field}}'] ) ) : '' ); // phpcs:ignore WordPress.Security.NonceVerification
}
